/* Foolish Swan 57 by Juanes200122 — https://uiverse.io/Juanes200122/foolish-swan-57 */
.container {
  position: absolute;
  width: 100%;
  height: 100%;
  perspective: 1000px;
  background: linear-gradient(45deg, #000000 25%, transparent 25%),
    linear-gradient(
      -135deg,
      #000000 25%,
      transparent 25%,
      transparent 75%,
      #000000 75%,
      #000000
    );
  background-size: 50px 50px;
}
